android.extraProguardRules:
# Paymob: the RN bridge and the native checkout SDK. The SDK inflates its
# sheet through data binding and resolves classes reflectively, and it ships
# from JitPack without consumer rules, so it has to be kept by hand.
-keep class com.paymobreactnative.** { *; }
-keep class com.paymob.** { *; }
-dontwarn com.paymob.**

# Analytics SDKs look classes up by name at runtime.
-keep class com.mixpanel.** { *; }
-dontwarn com.mixpanel.**
-keep class com.microsoft.clarity.** { *; }
-dontwarn com.microsoft.clarity.**

# Expo resolves modules through a reflective registry.
-keep class expo.modules.** { *; }
-keep class * extends expo.modules.core.interfaces.Package { *; }
-keep class * extends expo.modules.kotlin.modules.Module { *; }

# React Native bridge surfaces reached from JS or JNI.
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclasseswithmembernames class * { native <methods>; }

# Kotlin metadata is read reflectively by the Expo and Paymob Kotlin modules.
-keep class kotlin.Metadata { *; }
-dontwarn kotlinx.**

-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
